    // IC1 (#226): every menu and context-menu item that runs a command shows
    // an icon of the set: an iconRole on the item, or on the submenu it
    // opens. A check item needs none: its check mark stands in the icon's
    // place, as in MuseScore's menus. Nor does an entry named by its data (a
    // recent file, a macro, a sort key, a panel, a suggestion), whose
    // submenu has the icon, nor an item a later card removes; those are
    // exempted here by the text that identifies them, and an exemption that
    // matches no item fails too. docs/qt/ux/menu-icon-gaps.md lists them.
    void everyMenuItemHasAnIcon()
    {
        using menu_icon_scan::Exemption;
        const QString main = QStringLiteral("Main.qml");
        const QString recent = QStringLiteral("a recent file");
        const QList<Exemption> exemptions{
            {main, QStringLiteral(R"("recentSubtitles" + index)"), recent},
            {main, QStringLiteral(R"("recentAudio" + index)"), recent},
            {main, QStringLiteral(R"(text: qsTr("None"))"), QStringLiteral("the empty list's placeholder")},
            {QStringLiteral("RecentFilesMenu.qml"), QStringLiteral("menu.prefix + index"), recent},
            {QStringLiteral("RecentFilesMenu.qml"), QStringLiteral(R"(text: qsTr("None"))"),
             QStringLiteral("the empty list's placeholder")},
            {QStringLiteral("VideoContextMenu.qml"), QStringLiteral(R"("RecentSubtitles" + index)"), recent},
            {QStringLiteral("VideoContextMenu.qml"), QStringLiteral(R"("RecentVideos" + index)"), recent},
            {QStringLiteral("VideoContextMenu.qml"), QStringLiteral(R"("videoMenuFilter" + index)"),
             QStringLiteral("a DirectShow filter, under Filters")},
            {main, QStringLiteral(R"("sortAll_" + modelData.key)"), QStringLiteral("a sort key, under Sort all lines")},
            {main, QStringLiteral(R"("sortSelected_" + modelData.key)"),
             QStringLiteral("a sort key, under Sort selected lines")},
            {QStringLiteral("MacroMenuEntries.qml"), QStringLiteral(R"("macro_" + macro.name)"),
             QStringLiteral("a macro of the loaded scripts")},
            {main, QStringLiteral(R"("panelMenu" + modelData.uniqueName)"), QStringLiteral("a panel, under Panels")},
            {main, QStringLiteral("root.app.replaceEditorMisspell"), QStringLiteral("a spelling suggestion")},
            {QStringLiteral("AutomationDialog.qml"), QStringLiteral(R"("dialogPreset_" + modelData)"),
             QStringLiteral("a script dialog's preset, under Presets")},
            {QStringLiteral("AutomationDialog.qml"), QStringLiteral(R"("dialogDeletePreset_" + modelData)"),
             QStringLiteral("a script dialog's preset, under Delete preset")},
            {QStringLiteral("MainTitleBar.qml"), QStringLiteral("bar.foldFrom + index"),
             QStringLiteral("a menu of the title bar folded into More (the menus have no icons)")},
            {QStringLiteral("FontPicker.qml"), QStringLiteral(R"(text: qsTr("No catalogs yet"))"),
             QStringLiteral("the empty list's placeholder")},
            {QStringLiteral("FontCatalogBar.qml"), QStringLiteral(R"(text: qsTr("No catalogs yet"))"),
             QStringLiteral("the empty list's placeholder")},
        };
        const QStringList problems = menu_icon_scan::itemsWithoutIcons(QStringLiteral(HIKARI_UI_SOURCE_DIR), exemptions);
        if (!problems.isEmpty())
            QFAIL(qPrintable(problems.join(QLatin1Char('\n'))));
    }

    // The scan behind everyMenuItemHasAnIcon finds an item without an icon
    // where it stands (one line, several lines, an Instantiator's delegate,
    // a submenu) and skips the others.
    void menuIconScanFindsItemsWithoutIcons()
    {
        QTemporaryDir dir;
        QVERIFY(dir.isValid());
        const auto write = [&](const QString &name, const QByteArray &text) {
            QFile file(dir.filePath(name));
            QVERIFY(file.open(QIODevice::WriteOnly));
            file.write(text);
        };
        write(QStringLiteral("Probe.qml"), R"(Item {
    ShellMenu {
        ShellMenuItem { iconRole: "save"; text: qsTr("Save {x}") }
        ShellMenuItem { text: qsTr("One line") }
        ShellMenuItem {
            // iconRole: "commented out"
            text: "Several lines"
            onTriggered: { const iconRole = "in a handler" }
        }
        ShellMenuItem { text: qsTr("Checked"); checkable: true }
        ShellMenuItem { text: qsTr("Not checked"); checkable: false }
        Instantiator { delegate: ShellMenuItem { text: modelData } }
        ShellMenu { title: qsTr("Submenu") }
        ShellMenu { iconRole: "sort"; title: qsTr("Sorted") }
        ProbeMenu {}
        ShellMenuItem { objectName: "exempt"; text: "Exempt" }
    }
}
)");
        write(QStringLiteral("ProbeMenu.qml"), R"(ShellMenu {
    title: "Derived"
    delegate: ShellMenuItem {}
    ShellMenuItem { text: "In the derived menu" }
})");
        const QStringList problems = menu_icon_scan::itemsWithoutIcons(
            dir.path(), {{QStringLiteral("Probe.qml"), QStringLiteral(R"("exempt")"), QString()},
                         {QStringLiteral("Probe.qml"), QStringLiteral("nothing here"), QString()}});
        const QStringList expected{
            QStringLiteral(R"(Probe.qml:4: ShellMenuItem qsTr("One line") has no iconRole)"),
            QStringLiteral(R"(Probe.qml:5: ShellMenuItem "Several lines" has no iconRole)"),
            QStringLiteral(R"(Probe.qml:11: ShellMenuItem qsTr("Not checked") has no iconRole)"),
            QStringLiteral(R"(Probe.qml:12: ShellMenuItem modelData has no iconRole)"),
            QStringLiteral(R"(Probe.qml:13: ShellMenu qsTr("Submenu") has no iconRole)"),
            QStringLiteral(R"(Probe.qml:15: ProbeMenu (no text) has no iconRole)"),
            QStringLiteral(R"(ProbeMenu.qml:4: ShellMenuItem "In the derived menu" has no iconRole)"),
            QStringLiteral(R"(Probe.qml: the exemption "nothing here" matches no menu item)"),
        };
        QStringList sorted = problems;
        sorted.sort();
        QStringList want = expected;
        want.sort();
        QCOMPARE(sorted, want);
    }

    // D1: the keyboard placement window expresses drag placements and resizes.
    void placementWindowMovesTabsAndResizes()
    {
        QVERIFY(application->openFile(episode)); // SH2: the panels, not Home
        auto *root = engine->rootObjects().first();
        auto *placement = root->findChild<QQuickWindow *>(QStringLiteral("placementWindow"));
        QVERIFY(placement);
        auto *audioDock = root->findChild<QObject *>(QStringLiteral("audioDock"));
        QVERIFY(QMetaObject::invokeMethod(root->findChild<QObject *>(QStringLiteral("movePanel")), "triggered"));
        QTRY_VERIFY(placement->isVisible());
        auto *panelBox = findItem(placement->contentItem(), QStringLiteral("placementPanel"));
        auto *kindBox = findItem(placement->contentItem(), QStringLiteral("placementKind"));
        auto *targetBox = findItem(placement->contentItem(), QStringLiteral("placementTarget"));
        QVERIFY(panelBox && kindBox && targetBox);
        panelBox->setProperty("currentIndex", 1);  // Audio
        kindBox->setProperty("currentIndex", 1);   // Left of
        targetBox->setProperty("currentIndex", 4); // Grid (after TM1's Original text)
        QVERIFY(QMetaObject::invokeMethod(findItem(placement->contentItem(), QStringLiteral("placementMove")), "click"));
        // Audio sits left of the Grid, in the Grid's row.
        auto *audio = item("audioPanel");
        auto *gridPanel = item("gridPanel");
        QTRY_VERIFY(audio->mapToScene(QPointF(0, 0)).x() < gridPanel->mapToScene(QPointF(0, 0)).x());
        // (their bodies start lower under the Grid's tab bar: compare the groups)
        QCOMPARE(qRound(groupTop(audio)), qRound(groupTop(gridPanel)));
        QTRY_VERIFY(audio->hasActiveFocus()); // the moved panel keeps the focus

        // Numeric resize: wider by 60 px.
        const QSize before = application->workspaceLayout().panelSize(audioDock);
        QVERIFY(before.isValid());
        auto *width = findItem(placement->contentItem(), QStringLiteral("placementWidth"));
        auto *height = findItem(placement->contentItem(), QStringLiteral("placementHeight"));
        QCOMPARE(width->property("value").toInt(), before.width());
        width->setProperty("value", before.width() + 60);
        QVERIFY(QMetaObject::invokeMethod(findItem(placement->contentItem(), QStringLiteral("placementResize")), "click"));
        QTRY_COMPARE(application->workspaceLayout().panelSize(audioDock).width(), before.width() + 60);
        QCOMPARE(height->property("value").toInt(), application->workspaceLayout().panelSize(audioDock).height());

        // Tab with the Grid: both in one place.
        kindBox->setProperty("currentIndex", 0);
        QVERIFY(QMetaObject::invokeMethod(findItem(placement->contentItem(), QStringLiteral("placementMove")), "click"));
        QTRY_COMPARE(audio->mapToScene(QPointF(0, 0)), gridPanel->mapToScene(QPointF(0, 0)));
        placement->close();
    }

    // D1 native gate: Float leaves the focus on the panel, in its new window;
    // F6 and Shift+F6 activate that window and the main one; Show focuses a
    // floating panel. Qt reports a floating panel's window active whenever
    // the main window is, so this checks the application's focus window.
    void floatF6AndShowActivateTheFloatingPanelsWindow()
    {
        QVERIFY(application->openFile(episode));
        auto *root = engine->rootObjects().first();
        item("editingGrid")->forceActiveFocus();
        QVERIFY(QMetaObject::invokeMethod(named("panelFloatEditor"), "triggered"));
        QTRY_VERIFY(item("editorPanel")->window() != window);
        QWindow *floating = item("editorPanel")->window();
        if (!becomesFocusWindow(floating))
            QSKIP("The window manager did not give the new floating window the focus");
        QTRY_VERIFY(item("editorPanel")->hasActiveFocus()); // focus-after-float

        // F6 from the floating Line editor: the Grid, in the main window.
        QTest::keyClick(floating, Qt::Key_F6);
        if (!becomesFocusWindow(window))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_COMPARE(focusedPanel(), QStringLiteral("gridPanel"));
        // Shift+F6 from the Grid: back into the floating Line editor.
        press(Qt::Key_F6, Qt::ShiftModifier);
        if (!becomesFocusWindow(floating))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_VERIFY(item("editorPanel")->hasActiveFocus());
        // Shift+F6 again: Audio, in the main window.
        QTest::keyClick(floating, Qt::Key_F6, Qt::ShiftModifier);
        if (!becomesFocusWindow(window))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_COMPARE(focusedPanel(), QStringLiteral("audioPanel"));
        // F6 from Audio: into the floating Line editor.
        press(Qt::Key_F6);
        if (!becomesFocusWindow(floating))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_VERIFY(item("editorPanel")->hasActiveFocus());

        // View > Panels > Line editor > Show from the main window focuses it.
        window->requestActivate();
        item("editingGrid")->forceActiveFocus();
        if (!becomesFocusWindow(window))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QVERIFY(QMetaObject::invokeMethod(named("panelShowEditor"), "triggered"));
        if (!becomesFocusWindow(floating))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_VERIFY(item("editorPanel")->hasActiveFocus());

        // Dock: the panel keeps the focus, back in the main window.
        QVERIFY(QMetaObject::invokeMethod(named("panelDockEditor"), "triggered"));
        QTRY_COMPARE(item("editorPanel")->window(), window);
        if (!becomesFocusWindow(window))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        QTRY_COMPARE(focusedPanel(), QStringLiteral("editorPanel"));

        // Float it again: the main window keeps no focused item, so when it
        // is activated again (by the window manager) the Grid takes the focus.
        QVERIFY(QMetaObject::invokeMethod(named("panelFloatEditor"), "triggered"));
        QTRY_VERIFY(item("editorPanel")->window() != window);
        if (!becomesFocusWindow(item("editorPanel")->window()))
            QSKIP("The window manager refused the shell's activation request (its focus-stealing policy)");
        window->requestActivate();
        if (!becomesFocusWindow(window))
            QSKIP("The window manager did not activate the main window");
        QTRY_COMPARE(focusedPanel(), QStringLiteral("gridPanel"));
        QVERIFY(root);
    }

