        h.select(hotkeyPosition(QStringLiteral("Global Next frame")));
        h.optionsMap(QStringLiteral("Alt-N"), 0, QStringLiteral("cancel"));
        h.commitOptions();
        item("videoPanel")->forceActiveFocus();
