        QVERIFY((dialog = openAppearance()) != nullptr);
        click("appearanceFollowSystem");
        QVERIFY(QMetaObject::invokeMethod(settingsButton("settingsOk"), "click"));
        QTRY_VERIFY(!dialog->property("visible").toBool());
