        QCOMPARE(cps->property("text").toString(), QStringLiteral("15/15"));
        QCOMPARE(application->editor().cpsWarning(), false);
        QCOMPARE(item("cpsCounterValue")->property("text").toString(), QStringLiteral("15"));
