        QVERIFY(QMetaObject::invokeMethod(keyMenu, "aboutToShow"));
        QCOMPARE(keyMenu->property("rows").toList().size(), 1);
        QVERIFY(QMetaObject::invokeMethod(named("recentKeyframes0"), "triggered"));
